import{_ as t,c as o,o as a,ah as p,ao as s,ap as i}from"./chunks/framework.Dq2_gudl.js";const m=JSON.parse('{"title":"다시 만날 수 있을까요? — 동물과 천국에 대한 성경의 소망","description":"반려동물을 잃은 뒤 가장 깊은 질문: 그 아이가 천국에 있을까요? 로마서와 이사야, 요한계시록이 주는 소망.","frontmatter":{"title":"다시 만날 수 있을까요? — 동물과 천국에 대한 성경의 소망","description":"반려동물을 잃은 뒤 가장 깊은 질문: 그 아이가 천국에 있을까요? 로마서와 이사야, 요한계시록이 주는 소망."},"headers":[],"relativePath":"ko/pets-in-heaven/will-i-see-my-pet-again.md","filePath":"ko/pets-in-heaven/will-i-see-my-pet-again.md"}'),l={name:"ko/pets-in-heaven/will-i-see-my-pet-again.md"};function n(r,e,h,c,d,g){return a(),o("div",null,[...e[0]||(e[0]=[p('<div class="pl-quote"><p>「저는 천국에 갈 거라는 걸 알아요. 그저 알고 싶은 건 — 그 아이도 거기서 저를 기다리고 있을까요?」</p><p class="pl-quote-soft">동물 친구를 잃은 사람들이 가장 많이 하고, 가장 꺼내기 어려운 질문입니다.</p></div><section class="pl-section"><h2>먼저 솔직한 한마디</h2><p>성경은 「모든 반려동물이 천국에서 주인과 다시 만난다」고 적은 구절을 남기지 않았습니다. 그렇게 단정하는 사람은 성경이 말하는 것보다 더 나아간 것입니다.</p><p>그러나 그것으로 절망하지는 마세요. 성경이 그리는 그림은 우리가 생각하는 것보다 훨씬 넓습니다. 하나님의 구원은 「인간의 영혼 몇 개를 구해내는 일」이 아니라 <strong>온 피조물의 새로워짐</strong>입니다. 그리고 동물은 그 그림 안에 처음부터 끝까지 있습니다.</p></section><section class="pl-section"><h2>1. 피조물도 우리와 함께 기다립니다</h2><blockquote><p><strong>로마서 8:19-22</strong></p><p>&quot;For the earnest expectation of the creature waiteth for the manifestation of the sons of God… For we know that the whole creation groaneth and travaileth in pain together until now.&quot;</p></blockquote><p>바울은 여기서 놀라운 말을 합니다. 탄식하며 기다리는 것은 사람만이 아닙니다. <em>피조물 자체</em>도 함께 탄식하며 구원을 기다립니다. 동물은 구원 밖에 남겨진 배경이 아니라, 우리와 같은 결말을 바라보고 있습니다.</p><p>당신이 「그 아이는 착했는데, 그냥 사라지는 건 말이 안 돼」라고 느낄 때, 그 감정은 온 피조물이 느끼는 것과 같습니다. 성경은 그 아픔이 반드시 응답될 것이라고 말합니다.</p></section><section class="pl-section"><h2>2. 하나님이 만드실 세상에는 동물이 있습니다</h2><blockquote><p><strong>이사야 11:6-9</strong></p><p>&quot;The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them.&quot;</p></blockquote><p>이사야가 본 미래는 빛과 구름만 있는 세상이 아니었습니다. 그는 이리와 어린 양, 표범과 염소, 송아지와 사자, 살진 짐승을 보았습니다. 서로 해치지 않고 평안히 눕는 세상입니다.</p><p>하나님의 뜻이 「동물은 이생까지만 쓰고 끝」이었다면, 그들을 약속 안에 두지 않으셨을 것입니다. 두셨습니다.</p><p>요한계시록은 새 하늘과 새 땅을 이렇게 묘사합니다.</p><blockquote><p><strong>요한계시록 21:4-5</strong></p><p>&quot;And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away. …Behold, I make all things new.&quot;</p></blockquote><p>「다시 사망이 없고」는 온 피조물을 향한 선언입니다. 당신의 아이가 통과한 그 죽음도 사라질 것들 중 하나입니다.</p></section><section class="pl-section"><h2>3. 그렇다면 어디까지 소망할 수 있을까요?</h2><p>우리는 소망할 수 있습니다. 하나님이 지으신 것을 버리지 않으시기 때문입니다. 그리스도의 부활이 새 창조의 첫 열매이며, 그 범위가 「모든 것」이라고 성경이 말하기 때문입니다. 동물을 지으시고 기뻐하신 하나님이 갑자기 그들을 돌보지 않게 되지는 않으시기 때문입니다.</p><p>「같은 그 아이일까」, 「나를 기억할까」에 대해 성경은 세부를 말하지 않습니다. 대신 신뢰할 수 있는 하나님을 주시고, 세부는 그분의 손에 맡기셨습니다. 이 침묵은 우리를 괴롭히기 위한 것이 아니라, 알 수 없는 일을 선한 손에 맡기라는 초대입니다.</p><p class="pl-quote-soft">원하신다면 이렇게 기도해 보세요:</p></section><div class="pl-quote"><p>「주님, 천국의 세부는 모르지만 주님이 선하시다는 것을 믿습니다.<br>주님이 그 아이를 지으셨고, 그 아이의 하루하루를 돌보셨고, 지금 제 눈물도 보고 계십니다.<br>그 아이를 주님 손에 맡깁니다. 제 자신을 맡기듯이요.<br>주님의 약속에 그 아이의 자리가 있다면 감사합니다.<br>이제 누군가 그 아이를 돌봐야 한다면, 그게 주님이라서 다행입니다. 아멘.」</p></div><section class="pl-section"><h2>유난히 힘든 날에</h2><p>시편 기자는 이렇게 썼습니다. 「여호와여 주께서 사람과 짐승을 보존하시나이다」(시편 36:6). 짧은 구절이지만, 동물을 하나님의 보존하심 안에 직접 넣은 드문 구절 중 하나입니다.</p><p>당신의 아이는 「사람과 짐승을 보존하시는」 하나님께 속해 있습니다. 오늘 필요한 것은 완전한 답이 아니라 이것일지도 모릅니다. 그 아이는 하나님의 손에 있고, 하나님은 선하시다.</p><p><a href="/ko/pets-in-heaven/">← Pets in Heaven으로 돌아가기</a> ｜ 다음 글: <a href="/ko/pets-in-heaven/not-one-sparrow-forgotten">참새 한 마리도 잊히지 않습니다</a></p></section><div class="pl-cta"><h2>그 아이의 이름을 적어 보세요.</h2><p>이름, 가장 좋아하던 자리, 미처 하지 못한 말을 적어 보세요. PetLoss는 계정도 업로드도 없이, 재촉하지 않고 천천히 정리하도록 곁에 있겠습니다.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">App Store에서 다운로드</a></div><div class="pl-bible"><h3>말씀이 계속 곁에 있도록</h3><p>이 글의 모든 구절은 성경에서 왔습니다. 무지개 성경 위젯 앱으로 언제든 말씀을 읽고 매일 말씀 위젯을 설정해 보세요. 그리운 날들에 작은 등불이 되어 줄 것입니다.</p><div class="pl-bible-shots"><figure><img src="'+s+'" alt="Rainbow Bible 홈 화면 위젯 — 2 Timothy 2:13" loading="lazy"><figcaption>매일 말씀을 홈 화면에</figcaption></figure><figure><img src="'+i+'" alt="Rainbow Bible — 하늘나라의 반려동물 주제, 마태복음 10:29-31" loading="lazy"><figcaption>「하늘나라의 반려동물」 주제로 전환해 읽기</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">App Store에서 무지개 성경 위젯 받기</a></div>',9)])])}const u=t(l,[["render",n]]);export{m as __pageData,u as default};
